function renderEditor(){const r=state.record,d=disabled(),m=r.modelSnapshot||modelById(r.modelId)||{checkItems:[]};const checks=m.checkItems||[];const appearance=state.catalog.appearanceOptions.map(option=>(r.appearanceSnapshot||[]).find(saved=>saved.code===option.code)||option);for(const x of r.appearanceSnapshot||[])if(!appearance.some(y=>y.code===x.code))appearance.push(x);const groups=[['refurbishment','Refurbishment',['like_new','good','acceptable'],'Refurbishment requires every inspection result to pass.'],['repair','Repair',['rok','scrap'],'ROK requires all functions to be inspected. SCRAP requires a reason.'],['wfr','WFR',['awp','needs_analysis'],'Waiting, not completed. Continue this record later.']];
 shell(`<div class="heading"><div><h1>${e(t('Work Record'))}</h1><span class="badge ${e(r.status)}">${e(t(r.status==='completed'?'Completed':'In Progress'))}</span>${!editable()?`<span class="badge">${e(t('View-only'))}</span>`:''}</div><div><small>${r.updatedAt?`${e(t('Last saved'))} ${e(date(r.updatedAt))} · ${e(t('Version'))} ${r.version}`:e(t('New record'))}</small><button id="reload-record" ${r.id?'':'disabled'}>${e(t('Reload latest record'))}</button></div></div><div id="form-error" class="error-box" role="alert" tabindex="-1" hidden></div>${r.modelId&&!m.checkItems?.length?`<p class="error-box">${e(t('No active models. Ask an administrator to add a model and checklist.'))}</p>`:''}<div class="identity">${input('sn','Serial Number',r.sn,`${d} required maxlength="200"`)}<label for="modelId">${e(t('Model'))}<select id="modelId" ${d} ${r.id?'disabled':''}>${!r.id?option('',t('Select model'),r.modelId):''}${r.modelId&&!modelById(r.modelId)?option(r.modelId,modelLabel(m),r.modelId):''}${state.catalog.models.filter(x=>x.active||String(x.id)===String(r.modelId)).map(x=>option(x.id,modelLabel(r.id&&String(x.id)===String(r.modelId)?m:x),r.modelId)).join('')}</select></label>${input('productSku','Product SKU',r.productSku,'disabled')}${input('workOrder','Work Order',r.workOrder||'—','disabled')}</div><div class="banner"><span id="sn-history-hint" role="status">${e(t(state.snLookup?.sn===r.sn.trim()&&state.snLookup.items.length?'Previous records found for this SN. Records owned by others are view-only.':'Previous visits for the exact SN are available read only.'))}</span><button id="view-history">${e(t('View History'))}</button></div><div class="editor-grid"><section class="panel checks"><div class="panel-head"><h2>${e(t('Functional Checks'))}</h2><div id="knowledge-tools"></div></div><div id="selected-faults" class="fault-chips"></div>${checks.some(c=>guidanceValue(c,'label').missing)?`<small class="guidance-missing check-language-warning">${e(t('English guidance not supplied. Original source shown.'))}</small>`:''}<div class="check-table-wrap"><table><thead><tr><th>${e(t('Check Item'))}</th><th>${e(t('Inspection Result'))}</th></tr></thead><tbody>${checks.map(c=>`<tr><td>${guidanceField(c,'label')||e(c.code)}</td><td><div class="functional-options" role="radiogroup" aria-label="${e(guidanceLabel(c,'label',c.code))}">${['not_tested','pass','fail'].map((value,i)=>`<label class="functional-choice ${value}"><input type="radio" name="functional-initial-${e(c.code)}" data-functional-check="${e(c.code)}" data-check-code="${e(c.code)}" data-check-phase="initial" value="${value}" ${(r.checks?.initial?.[c.code]||'not_tested')===value?'checked':''} ${d}><span>${e(t(['Not Tested','Pass','Fail'][i]))}</span></label>`).join('')}</div></td></tr>`).join('')}</tbody></table></div></section><section class="panel defect-panel" id="defect-panel"><h2 id="defect-heading">${e(t('Defect remark'))}</h2><div class="stack"><textarea id="issueNotes" aria-labelledby="defect-heading" ${d}>${e(r.issueNotes)}</textarea></div></section><section class="panel notes-panel"><h2>${e(t('Condition & Notes'))}</h2><div class="appearances">${appearance.map(a=>`<label><input type="checkbox" data-appearance="${e(a.code)}" ${r.appearanceCodes.includes(a.code)?'checked':''} ${d}>${e(label(a))}</label>`).join('')}</div><div class="stack">${textarea('appearanceNotes','Appearance Notes',r.appearanceNotes,d)}</div></section><section class="panel evidence-section"><div class="panel-head"><h2>${e(t('Evidence Photos'))}</h2><span class="badge">${r.photos?.length||0}</span></div><small>${e(t('Optional'))} · ${e(t('Photos are optional. JPEG or PNG, 8 MiB each, up to 20 photos.'))}</small><div id="photos" class="photos">${r.photos?.map((p,i)=>`<div class="photo"><a href="${e(photoUrl(p))}" target="_blank" rel="noopener"><img src="${e(photoUrl(p))}" alt="${e(t('Evidence Photo'))} ${i+1}" loading="lazy"></a>${editable()?`<button class="danger" data-delete-photo="${e(p.id)}">${e(t('Remove'))}</button>`:''}</div>`).join('')||`<small>${e(t('No photos'))}</small>`}</div>${editable()?`<div class="photo-tools"><div class="photo-picker"><label for="photo-file">${e(t('Evidence Photos'))}</label><input id="photo-file" class="sr-only" type="file" accept="image/png,image/jpeg" tabindex="-1" aria-describedby="photo-selection"><button id="choose-photo" type="button">${e(t('Choose Photo'))}</button><small id="photo-selection" role="status">${e(t(state.photoDraft?'Photo selected':'No photo selected'))}</small></div><button id="upload-photo">${e(t('Upload Photo'))}</button></div>`:''}</section><section class="panel materials"><div class="panel-head"><h2>${e(t('Material Usage'))}</h2><button class="primary" id="open-bom" ${d}>+ ${e(t('Add BOM Items'))}</button></div><p class="muted">${e(t('Only model BOM items; default quantity is 1. Packaging is recorded the same way.'))}</p><p><span class="badge">${r.materials.length} ${e(t('items'))}</span></p><div class="table-wrap"><table><thead><tr>${['Part SKU','Part Description','Qty','Action'].map(x=>`<th>${e(t(x))}</th>`).join('')}</tr></thead><tbody id="material-rows">${r.materials.map((x,i)=>`<tr data-material-row="${e(x.bomId)}"><td>${e(x.sku)}</td><td>${partDescription(x)}${x.unit?`<small> · ${e(x.unit)}</small>`:''}${capHint(x)}</td><td><input class="quantity" data-material-qty="${i}" type="number" ${quantityAttributes(x)} value="${e(x.quantity)}" aria-label="${e(x.sku)} ${e(t('Qty'))}" ${d}></td><td><button class="danger" data-remove-material="${i}" ${d}>${e(t('Remove'))}</button></td></tr>`).join('')}</tbody></table>${!r.materials.length?`<p class="empty">${e(t('No materials added'))}</p>`:''}</div><div class="info">${e(t('Only model BOM items; default quantity is 1. Packaging is recorded the same way.'))}</div></section></div><section class="panel outcomes"><div class="panel-head"><div class="row"><h2>${e(t('Outcome'))}</h2><span class="muted">${e(t('Choose ONE outcome across Refurbishment, Repair and WFR.'))}</span></div><span class="badge">${e(outcomeLabel(r.outcome))}</span></div><div class="outcome-grid">${groups.map(([group,title,codes,hint])=>`<section class="outcome-group"><h3>${e(t(title))}</h3><div class="outcome-options">${codes.map(code=>`<label class="radio-option"><input type="radio" name="outcome" value="${code}" ${r.outcome===code?'checked':''} ${d}>${e(outcomeLabel(code))}</label>`).join('')}</div><small>${e(t(hint))}</small></section>`).join('')}</div>${r.outcome==='scrap'?`<div class="spaced">${textarea('scrapReason','Scrap Reason',r.scrapReason,`${d} required`)}</div>`:''}</section>${state.history&&r.status!=='completed'&&String(r.ownerId)===String(state.session.user.id)?`<button id="resume-record">${e(t('Resume Record'))}</button>`:''}${state.correction?`<section class="panel outcomes">${textarea('correctionReason','Correction Reason',state.correctionReason||'','required')}</section>`:''}<div class="actions"><small>${e(t('Only the owner can continue. Completed records require a reasoned admin correction.'))}</small><div class="row"><button id="view-audit" ${r.id?'':'disabled'}>${e(t('View Audit'))}</button>${state.correction?`<button id="cancel-correction">${e(t('Cancel'))}</button><button class="primary" id="save-correction">${e(t('Save Correction'))}</button>`:editable()?`<button id="save-record">${e(t(waiting(r)?'Save WFR':'Save Progress'))}</button>${waiting(r)?'':`<button class="primary" id="complete-record">${e(t('Complete & Lock'))}</button>`}`:isAdmin()&&!state.history?`<button class="primary" id="start-correction">${e(t('Admin Correction'))}</button>`:''}</div></div>`);
 for(const key of ['sn','sourcePallet','storagePallet','workDate','appearanceNotes','issueNotes','translatedAppearanceNotes','translatedIssueNotes','scrapReason'])bind(key,'input',ev=>{r[key]=ev.target.value;state.dirty=true;if(key==='sn')scheduleSnLookup();if(key==='appearanceNotes'||key==='issueNotes'){const translated=key==='appearanceNotes'?'translatedAppearanceNotes':'translatedIssueNotes';if(!r[key].trim()){r[translated]='';if($(translated))$(translated).value='';}if($(translated))$(translated).disabled=!editable()||!r[key].trim();}});bind('correctionReason','input',ev=>{state.correctionReason=ev.target.value;state.dirty=true;});bind('modelId','change',ev=>{r.modelId=ev.target.value?Number(ev.target.value):'';r.modelSnapshot=structuredClone(modelById(r.modelId));r.productSku=r.modelSnapshot?.productSku||'';r.checks={initial:{}};r.materials=[];r.faultCodes=[];r.faultSnapshot=[];state.knowledge=null;state.dirty=true;renderEditor();loadKnowledge();});
 document.querySelectorAll('[data-functional-check]').forEach(el=>el.addEventListener('change',()=>{r.checks[el.dataset.checkPhase]??={};r.checks[el.dataset.checkPhase][el.dataset.checkCode]=el.value;state.dirty=true;}));document.querySelectorAll('[data-appearance]').forEach(el=>el.addEventListener('change',()=>{r.appearanceCodes=toggleAppearance(r.appearanceCodes,el.dataset.appearance,el.checked);state.dirty=true;document.querySelectorAll('[data-appearance]').forEach(x=>x.checked=r.appearanceCodes.includes(x.dataset.appearance));}));document.querySelectorAll('input[name=outcome]').forEach(el=>el.addEventListener('change',()=>{r.outcome=el.value;state.dirty=true;renderEditor();}));document.querySelectorAll('[data-material-qty]').forEach(el=>el.addEventListener('input',()=>{r.materials[Number(el.dataset.materialQty)].quantity=el.value;state.dirty=true;}));document.querySelectorAll('[data-remove-material]').forEach(el=>el.addEventListener('click',()=>{r.materials.splice(Number(el.dataset.removeMaterial),1);state.dirty=true;renderEditor();}));
 renderKnowledge();if(!r.modelId)document.querySelectorAll('.editor-grid input,.editor-grid textarea,.editor-grid button,.outcomes input,.outcomes textarea,.outcomes button,#save-record,#complete-record,#save-correction').forEach(el=>el.disabled=true);bind('sn','keydown',ev=>{if(ev.key==='Enter'){ev.preventDefault();$('modelId')?.focus();}});bind('save-record','click',()=>saveRecord('save'));bind('complete-record','click',()=>saveRecord('complete'));bind('open-bom','click',()=>openBom());bind('reload-record','click',()=>{if((!state.dirty&&!state.photoDraft)||confirm(t('Discard unsaved changes and reload the latest version?')))return openRecord(r.id,state.historySn);});bind('view-history','click',()=>safeGo(()=>{state.view='history';state.historyQuery=r.sn;renderHistory();loadHistory(r.sn);}));bind('resume-record','click',()=>openRecord(r.id));bind('view-audit','click',auditDialog);bind('start-correction','click',()=>{state.correction=true;state.correctionReason='';renderEditor();});bind('cancel-correction','click',()=>safeGo(()=>openRecord(r.id)));bind('save-correction','click',()=>saveRecord(r.status==='completed'?'complete':'save'));bind('choose-photo','click',()=>$('photo-file').click());bind('photo-file','change',ev=>{state.photoDraft=ev.target.files[0]||null;state.dirty=true;$('photo-selection').textContent=t(state.photoDraft?'Photo selected':'No photo selected');});bind('upload-photo','click',uploadPhoto);document.querySelectorAll('[data-delete-photo]').forEach(b=>b.addEventListener('click',()=>deletePhoto(b.dataset.deletePhoto).catch(showError)));
}
async function saveRecord(action){if(action==='complete'&&state.photoDraft)throw new Error(t('Upload selected photo before completing.'));const r=state.record;validateMaterialQuantities(r.materials);if(!r.sn?.trim())throw new Error(t('Serial Number')+' '+t('Reason')+': required');if(!r.modelId)throw new Error(t('Select a model first.'));if(action==='complete'){const err=completionError(r);if(err)throw new Error(t({outcome:'Please choose an outcome.',wfr:'WFR cannot be completed. Save WFR instead.',inspection:'Complete all inspection items. Refurbishment requires all results to pass.',scrap:'Enter a scrap reason before completing this record.'}[err]));}if(state.correction&&!state.correctionReason?.trim())throw new Error(t('Correction reason is required.'));
 const controls=['save-record','complete-record','save-correction'].map($).filter(Boolean);controls.forEach(x=>x.disabled=true);try{if(!r.id){const created=await api('/api/records',{method:'POST',body:{sn:r.sn,modelId:r.modelId,workDate:r.workDate,productSku:r.productSku,sourcePallet:r.sourcePallet,storagePallet:r.storagePallet}});r.id=created.record.id;r.workOrder=created.record.workOrder;r.version=created.record.version;}
 const url='/api/records/'+encodeURIComponent(r.id);const body=recordInput(r,action);const data=state.correction?await api(url+'/corrections',{method:'POST',body:{version:r.version,reason:state.correctionReason,changes:body}}):await api(url,{method:'PUT',body});state.record=data.record;state.dirty=false;state.correction=false;renderEditor();notice(t('Saved successfully'));return true;
 }finally{controls.forEach(x=>x.disabled=false);}}
function photoUrl(p){if(!state.history)return p.url;const url=new URL(p.url,location.origin);url.searchParams.set('sn',state.historySn);return url.pathname+url.search;}
async function uploadPhoto(){const f=$('photo-file').files[0]||state.photoDraft;if(!f)return;if(!['image/png','image/jpeg'].includes(f.type)||f.size>8388608)throw new Error(t('File must be PNG or JPEG and at most 8 MiB.'));const reason=state.correction?state.correctionReason:null;if(state.correction&&!reason?.trim())throw new Error(t('Correction reason is required.'));state.photoDraft=null;try{if(!state.record.id||state.dirty)await saveRecord(state.correction&&state.record.status==='completed'?'complete':'save');const dataUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(f);});const data=await api('/api/records/'+state.record.id+'/photos',{method:'POST',body:{version:state.record.version,filename:f.name,contentBase64:dataUrl.split(',')[1],...(reason?{reason}:{})}});state.record=data.record;renderEditor();notice(t('Photo uploaded'));}catch(err){state.photoDraft=f;const failure=new Error(t('Upload failed. Your photo has not been saved. Please try again.'));failure.cause=err;if(err.status===422||err.status===413||err.status===409)failure.details={code:err.code,reason:errorMessage(err)};throw failure;}}
async function deletePhoto(id){const reason=state.correction?state.correctionReason:null;if(state.correction&&!reason?.trim())throw new Error(t('Correction reason is required.'));if(state.dirty)await saveRecord(state.correction&&state.record.status==='completed'?'complete':'save');const data=await api('/api/photos/'+encodeURIComponent(id),{method:'DELETE',body:{version:state.record.version,...(reason?{reason}:{})}});state.record=data.record;renderEditor();notice(t('Photo removed'));}
function dialog(id,title,body,footer='',className='',beforeClose=null){const previous=document.activeElement;$('modal-root').innerHTML=`<dialog id="${id}" class="${className}" aria-labelledby="dialog-title"><div class="dialog-head"><div><h2 id="dialog-title">${e(title)}</h2></div><button id="dialog-x" aria-label="${e(t('Close'))}">${e(t('Close'))}</button></div><div class="dialog-body">${body}</div>${footer?`<div class="dialog-footer">${footer}</div>`:''}</dialog>`;const d=$(id);const close=(force=false)=>{if(force!==true&&beforeClose&&!beforeClose())return false;d.close();d.remove();previous?.focus();return true;};d.addEventListener('cancel',ev=>{ev.preventDefault();close();});d.addEventListener('close',()=>{if(document.activeElement===document.body||document.activeElement===d||d.contains(document.activeElement))previous?.focus();});$('dialog-x').addEventListener('click',()=>close());d.showModal();return {d,close};}
async function openBom(retained=null){if(!state.record.modelId)throw new Error(t('Select a model first.'));const bomModelId=state.record.modelId;const bomRecord=state.record;const b=retained||{q:'',page:1,pending:new Map(),data:{items:[],total:0}};const modal=dialog('bom-dialog',t('Add Items from Model BOM'),`<section class="drawer-results"><form id="bom-search-form" class="search-row"><label class="grow">${e(t('Search part SKU or description'))}<input id="bom-search" autocomplete="off" value="${e(b.q)}"></label><button>${e(t('Search'))}</button></form><p id="bom-count" class="muted"></p><div id="bom-error" role="alert" class="error-box" hidden></div><table><thead><tr><th>${e(t('Select'))} / ${e(t('Part SKU'))}</th><th>${e(t('Part Description'))}</th><th>${e(t('Status'))}</th></tr></thead><tbody id="bom-results"></tbody></table><div class="pagination"><small id="bom-page"></small><div class="row"><button id="bom-prev">${e(t('Previous'))}</button><button id="bom-next">${e(t('Next'))}</button></div></div><div class="info">${e(t('Selections stay checked across searches and pages. No duplicate rows.'))}</div></section><aside class="pending"><h3 id="pending-count"></h3><small>${e(t('Pending items are not added until you click Add Selected Items.'))}</small><div id="bom-pending"></div></aside>`,`<small>${e(t('Only model BOM items; default quantity is 1. Packaging is recorded the same way.'))}</small><div class="row"><button id="bom-language" aria-label="${state.lang==='en'?'Switch to Chinese':'Switch to English'}">${state.lang==='en'?'ZH':'EN'}</button><button id="bom-cancel">${e(t('Cancel'))}</button><button class="primary" id="bom-add">${e(t('Add Selected Items'))}</button></div>`,'drawer',()=>!b.pending.size||confirm(t('Discard pending BOM selections?')));
 const renderPending=()=>{$('pending-count').textContent=b.pending.size+' '+t('Items to Add');$('bom-add').disabled=!b.pending.size;$('bom-pending').innerHTML=[...b.pending.values()].map(x=>`<div class="pending-item"><strong data-pending-sku>${e(x.sku)}</strong><p>${partDescription(x)}${capHint(x)}</p><div class="row"><label>${e(t('Qty'))}<input class="quantity" type="number" ${quantityAttributes(x)} value="${e(x.quantity)}" data-pending-qty="${e(x.id)}"></label><button class="danger" data-pending-remove="${e(x.id)}">${e(t('Remove'))}</button></div></div>`).join('');document.querySelectorAll('[data-pending-qty]').forEach(el=>el.addEventListener('input',()=>{b.pending.get(String(el.dataset.pendingQty)).quantity=el.value;}));document.querySelectorAll('[data-pending-remove]').forEach(el=>el.addEventListener('click',()=>{b.pending.delete(String(el.dataset.pendingRemove));renderBom();}));};
 const renderBom=()=>{$('bom-count').textContent=b.data.total+' '+t('items');$('bom-page').textContent=`${t('Page')} ${b.page} / ${Math.max(1,Math.ceil(b.data.total/50))}`;$('bom-prev').disabled=b.page<=1;$('bom-next').disabled=b.page*50>=b.data.total;$('bom-results').innerHTML=b.data.items.map(x=>{const on=state.record.materials.some(v=>String(v.bomId)===String(x.id));const selected=b.pending.has(String(x.id));return `<tr class="${on||selected?'selected':''}"><td><label><input type="checkbox" data-bom-select="${e(x.id)}" ${on||selected?'checked':''} ${on?'disabled':''}>${e(x.sku)}</label></td><td>${partDescription(x)}${capHint(x)}</td><td>${on?`<p class="duplicate-hint">${e(t('This item is already on the usage list. Update its quantity in the existing row.'))}</p><button data-locate-material="${e(x.id)}">${e(t('Locate usage row'))}</button>`:e(t(selected?'To add':'Not selected'))}</td></tr>`;}).join('')||`<tr><td colspan="3" class="empty">${e(t('No matching items in this model BOM. Check the part SKU or try another word.'))}</td></tr>`;document.querySelectorAll('[data-bom-select]').forEach(el=>el.addEventListener('change',()=>{const item=b.data.items.find(x=>String(x.id)===el.dataset.bomSelect);if(el.checked)b.pending.set(String(item.id),{...item,quantity:1});else b.pending.delete(String(item.id));renderBom();}));document.querySelectorAll('[data-locate-material]').forEach(el=>el.addEventListener('click',()=>{if(!modal.close())return;const row=[...document.querySelectorAll('[data-material-row]')].find(row=>row.dataset.materialRow===el.dataset.locateMaterial);row?.scrollIntoView({block:'center'});row?.querySelector('[data-material-qty]')?.focus();}));renderPending();};
 let loadSequence=0;const isCurrentLoad=sequence=>sequence===loadSequence&&$('bom-dialog')===modal.d&&modal.d.open&&state.record===bomRecord&&String(state.record.modelId)===String(bomModelId);
 const load=async()=>{const sequence=++loadSequence;try{const data=await api('/api/models/'+encodeURIComponent(bomModelId)+'/bom?'+new URLSearchParams({q:b.q,page:b.page,pageSize:50}));if(!isCurrentLoad(sequence))return;b.data=data;$('bom-error').hidden=true;renderBom();}catch(err){if(!isCurrentLoad(sequence))return;$('bom-error').hidden=false;$('bom-error').textContent=errorMessage(err);}};
 bind('bom-search','input',()=>{b.q=$('bom-search').value;});bind('bom-search-form','submit',ev=>{ev.preventDefault();b.q=$('bom-search').value;b.page=1;return load();});bind('bom-prev','click',()=>{b.page--;return load();});bind('bom-next','click',()=>{b.page++;return load();});bind('bom-language','click',()=>{b.q=$('bom-search').value;modal.close(true);return changeLanguage(()=>openBom(b));});bind('bom-cancel','click',()=>modal.close());bind('bom-add','click',()=>{validateMaterialQuantities([...b.pending.values()]);state.record.materials=mergeMaterials(state.record.materials,[...b.pending.values()].map(x=>({...x,quantity:Number(x.quantity)})));state.dirty=true;modal.close(true);renderEditor();});await load();if($('bom-dialog')===modal.d&&modal.d.open)$('bom-search').focus();
}
function renderHistory(){shell(`<div class="heading"><h1>${e(t('SN History'))}</h1></div><p class="muted">${e(t('Previous visits for the exact SN are available read only.'))}</p><form id="history-form" class="search-row">${input('history-sn','Exact full serial number',state.historyQuery||'','required autocomplete="off"')}<button class="primary">${e(t('Search'))}</button></form><div id="history-results"></div>`);bind('history-form','submit',ev=>{ev.preventDefault();return loadHistory($('history-sn').value);});if(state.historyItems.length)renderHistoryItems();}
async function loadHistory(sn){state.historyQuery=sn.trim();if(!state.historyQuery)return;state.historyItems=(await api('/api/sn-history?sn='+encodeURIComponent(state.historyQuery))).items;renderHistoryItems();}
function renderHistoryItems(){if(!$('history-results'))return;$('history-results').innerHTML=`<table><thead><tr>${['Work Order','Serial Number','Owner','Model','Status','Work Date','Outcome'].map(x=>`<th>${e(t(x))}</th>`).join('')}</tr></thead><tbody>${state.historyItems.map(r=>`<tr><td><button class="record-link" data-history-record="${e(r.id)}">${e(r.workOrder)}</button></td><td>${e(r.sn)}</td><td>${e(r.ownerName)}</td><td>${e(modelLabel(r.modelSnapshot))}</td><td>${e(t(r.status==='completed'?'Completed':'In Progress'))} · ${e(t('View-only'))}</td><td>${e(r.workDate)}</td><td>${e(outcomeLabel(r.outcome))}</td></tr>`).join('')||`<tr><td colspan="7" class="empty">${e(t('No records found'))}</td></tr>`}</tbody></table>`;document.querySelectorAll('[data-history-record]').forEach(b=>b.addEventListener('click',()=>openRecord(b.dataset.historyRecord,state.historyQuery).catch(showError)));}
async function auditDialog(){const data=await api('/api/records/'+state.record.id+'/audit'+(state.history?'?historySn='+encodeURIComponent(state.historySn):''));const modal=dialog('audit-dialog',t('Audit Trail'),data.items.map(a=>`<article class="audit-entry"><h3>${e(a.action)} · ${e(a.actorName)}</h3><small>${e(date(a.createdAt))}</small>${a.reason?`<p>${e(t('Reason'))}: ${e(a.reason)}</p>`:''}<div class="audit-pair"><div><strong>${e(t('Before'))}</strong><pre>${e(JSON.stringify(a.before,null,2))}</pre></div><div><strong>${e(t('After'))}</strong><pre>${e(JSON.stringify(a.after,null,2))}</pre></div></div></article>`).join('')||`<p>${e(t('No audit entries'))}</p>`,`<button id="audit-close">${e(t('Close'))}</button>`);bind('audit-close','click',modal.close);}
function passwordDialog(){if(state.dirty||state.photoDraft){notice(t('Save or discard unsaved changes before changing password.'));return;}const modal=dialog('password-dialog',t('Change Password'),`<form id="password-form" class="stack">${input('currentPassword','Current Password','','type="password" autocomplete="current-password" required')}${input('newPassword','New Password','','type="password" autocomplete="new-password" minlength="10" required')}<div id="password-error" role="alert"></div><button class="primary">${e(t('Save'))}</button></form>`);bind('password-form','submit',async ev=>{ev.preventDefault();try{await api('/api/account/password',{method:'POST',body:{currentPassword:$('currentPassword').value,newPassword:$('newPassword').value}});modal.close();clearSessionState();renderLogin();notice(t('Password updated. Sign in with your new password.'));}catch(err){$('password-error').textContent=errorMessage(err);}});}

async function loadAdmin(){state.view='admin';state.adminEdit=null;if(state.adminSection==='users')state.adminItems=(await api('/api/admin/users')).items;else if(state.adminSection==='models')state.adminItems=state.catalog.models;else if(state.adminSection==='appearance')state.adminItems=state.catalog.appearanceOptions;else{state.adminModel=state.adminModel||state.catalog.models[0]?.id||'';state.adminBomPage=state.adminBomPage||1;const data=state.adminModel?await api('/api/models/'+state.adminModel+'/bom?includeInactive=1&pageSize=50&page='+state.adminBomPage+'&q='+encodeURIComponent(state.adminBomQuery||'')):{items:[],total:0};state.adminItems=data.items;state.adminBomTotal=data.total;}renderAdmin();}
function renderAdmin(){const section=state.adminSection;const title=({users:'Users',models:'Models & Checklists',appearance:'Appearance Options',bom:'BOM'})[section];shell(`<div class="heading"><h1>${e(t('Administration'))}</h1><div><label>${e(t('Administration'))}<select id="admin-section">${Object.entries({users:'Users',models:'Models & Checklists',appearance:'Appearance Options',bom:'BOM'}).map(([k,v])=>option(k,t(v),section)).join('')}</select></label><button id="admin-new" class="primary">+ ${e(t('New Entry'))}</button></div></div><h2>${e(t(title))}</h2>${section==='bom'?`<div class="search-row"><label>${e(t('Model'))}<select id="admin-model-filter">${state.catalog.models.map(m=>option(m.id,modelLabel(m),state.adminModel)).join('')}</select></label><form id="admin-bom-search-form" class="search-row">${input('admin-bom-search','Search part SKU or description',state.adminBomQuery||'')}<button>${e(t('Search'))}</button></form></div>`:''}<div class="admin-layout"><section><div class="admin-table"><table><thead><tr><th>${e(t('Code'))}</th><th>${e(t(title))}</th><th>${e(t('Active'))}</th><th>${e(t('Action'))}</th></tr></thead><tbody>${state.adminItems.map((x,i)=>`<tr><td>${e(x.username||x.sku||x.code||x.id)}</td><td>${section==='bom'?partDescription(x):e(x.displayName||modelLabel(x)||label(x))}</td><td>${x.active?'✓':'—'}</td><td><button data-admin-edit="${i}">${e(t('Edit'))}</button></td></tr>`).join('')||`<tr><td colspan="4">${e(t('No records found'))}</td></tr>`}</tbody></table></div>${section==='bom'?`<div class="pagination"><small>${state.adminBomTotal} ${e(t('items'))} · ${e(t('Page'))} ${state.adminBomPage||1}</small><div class="row"><button id="admin-bom-prev" ${(state.adminBomPage||1)<=1?'disabled':''}>${e(t('Previous'))}</button><button id="admin-bom-next" ${(state.adminBomPage||1)*50>=state.adminBomTotal?'disabled':''}>${e(t('Next'))}</button></div></div>`:''}</section><section id="admin-editor"></section></div>${section==='bom'?`<section class="panel outcomes"><div class="panel-head"><h2>${e(t('Import BOM CSV'))}</h2><a class="button" href="/api/admin/bom/template" download>${e(t('CSV Template'))}</a></div><p class="muted">${e(t('Atomic import: all rows must be valid; existing or duplicate SKUs are rejected.'))}</p><form id="csv-form" class="stack"><label>${e(t('Choose CSV file'))}<input id="csv-file" type="file" accept=".csv,text/csv"></label>${textarea('csv-content','CSV content',state.adminCsvDraft||'','required')}<div><button id="csv-import" class="primary">${e(t('Import BOM CSV'))}</button></div><p id="csv-result" role="status"></p></form></section>`:''}`);
 bind('admin-section','change',ev=>safeGo(()=>{state.adminSection=ev.target.value;state.adminBomPage=1;loadAdmin().catch(showError);}));bind('admin-new','click',()=>safeGo(()=>{state.adminEdit={};renderAdminForm();}));document.querySelectorAll('[data-admin-edit]').forEach(b=>b.addEventListener('click',()=>safeGo(()=>{state.adminEdit=structuredClone(state.adminItems[Number(b.dataset.adminEdit)]);renderAdminForm();})));bind('admin-model-filter','change',ev=>safeGo(()=>{state.adminModel=ev.target.value;state.adminBomPage=1;loadAdmin().catch(showError);}));bind('admin-bom-search-form','submit',ev=>{ev.preventDefault();safeGo(()=>{state.adminBomQuery=$('admin-bom-search').value;state.adminBomPage=1;loadAdmin().catch(showError);});});bind('admin-bom-prev','click',()=>safeGo(()=>{state.adminBomPage--;loadAdmin().catch(showError);}));bind('admin-bom-next','click',()=>safeGo(()=>{state.adminBomPage++;loadAdmin().catch(showError);}));bind('csv-file','change',async()=>{if($('csv-file').files[0]){$('csv-content').value=await $('csv-file').files[0].text();state.dirty=true;}});bind('csv-content','input',()=>{state.adminCsvDraft=$('csv-content').value;state.dirty=true;});bind('csv-form','submit',async ev=>{ev.preventDefault();try{const data=await api('/api/admin/bom/import',{method:'POST',body:{modelId:Number(state.adminModel),csv:$('csv-content').value}});state.dirty=false;state.adminCsvDraft='';await loadAdmin();$('csv-result').textContent=t('Imported')+': '+data.created;notice(t('Imported')+': '+data.created);}catch(err){$('csv-result').textContent=errorMessage(err);$('csv-result').className='error-box';}});if(state.adminEdit)renderAdminForm();
}
function captureAdminDraft(){if(state.view!=='admin')return;if($('csv-content'))state.adminCsvDraft=$('csv-content').value;if(!state.adminEdit||!$('admin-form'))return;const x=state.adminEdit;for(const k of ['username','displayName','role','nameEn','nameZh','productSku','code','labelEn','labelZh','modelId','sku','descriptionEn','descriptionZh','unit','standardQty'])if($('admin-'+k))x[k]=$('admin-'+k).value;if($('admin-active'))x.active=$('admin-active').checked;if($('admin-checkItems'))x.checkItems=parseChecklist($('admin-checkItems').value,x.checkItems);if($('admin-password'))x.password=$('admin-password').value;state.adminCsvDraft=$('csv-content')?.value??state.adminCsvDraft;}
function renderAdminForm(){const x=state.adminEdit,section=state.adminSection,editing=Boolean(x.id||(section==='appearance'&&state.adminItems.some(v=>v.code===x.code)));const active=`<label class="radio-option"><input id="admin-active" type="checkbox" ${x.active!==false?'checked':''}>${e(t('Active'))}</label>`;let fields='';
 if(section==='users')fields=`${input('admin-username','Username',x.username||'',`${editing?'disabled':'required'} autocomplete="off"`)}${input('admin-displayName','Display Name',x.displayName||'','required')}<label>${e(t('Role'))}<select id="admin-role">${option('operator',t('Operator'),x.role)}${option('admin',t('Admin'),x.role)}</select></label>${editing?active:input('admin-password','Password',x.password||'','type="password" minlength="10" required autocomplete="new-password"')}`;
 if(section==='models')fields=`${input('admin-nameEn','Name (English)',x.nameEn||'','required')}${input('admin-nameZh','Name (Chinese)',x.nameZh||'')}${input('admin-productSku','Product SKU',x.productSku||'')}${textarea('admin-checkItems','Check items: code|English label|Chinese label, one per line',formatChecklist(x.checkItems),'required rows="7"')}<small>${e(t('English is required except for source-backed originals. Historical snapshots are preserved.'))}</small>${active}`;
 if(section==='appearance')fields=`${input('admin-code','Code',x.code||'',editing?'disabled':'required')}${input('admin-labelEn','Label (English)',x.labelEn||'','required')}${input('admin-labelZh','Label (Chinese)',x.labelZh||'')}${active}`;
 if(section==='bom')fields=`<label>${e(t('Model'))}<select id="admin-modelId">${state.catalog.models.map(m=>option(m.id,modelLabel(m),x.modelId||state.adminModel)).join('')}</select></label>${input('admin-sku','Part SKU',x.sku||'','required')}${input('admin-descriptionEn','Description (English)',x.descriptionEn||'',x.source?'':'required')}${input('admin-descriptionZh','Description (Chinese)',x.descriptionZh||'')}${input('admin-unit','Unit',x.unit||'pcs','required')}${input('admin-standardQty','Standard usage / maximum',x.standardQty??'','type="number" min="0.001" step="0.001"')}${active}`;
 $('admin-editor').innerHTML=`<form id="admin-form" class="panel stack"><h3>${e(t(editing?'Edit':'New Entry'))}</h3>${fields}<div id="admin-error" role="alert" class="error-box" hidden></div><button id="admin-save" class="primary">${e(t('Save'))}</button></form>${section==='users'&&editing?`<form id="admin-reset-form" class="panel stack outcomes">${input('admin-reset-password','New password','','type="password" autocomplete="new-password" minlength="10" required')}<button>${e(t('Reset Password'))}</button><p id="admin-reset-result" role="status"></p></form>`:''}`;
 $('admin-form').addEventListener('input',()=>state.dirty=true);bind('admin-form','submit',async ev=>{ev.preventDefault();const v=k=>$('admin-'+k)?.value??'';let body;if(section==='users')body={displayName:v('displayName'),role:v('role'),...(editing?{active:$('admin-active').checked}:{username:v('username'),password:v('password')})};if(section==='models')body={nameEn:v('nameEn'),nameZh:v('nameZh'),productSku:v('productSku'),active:$('admin-active').checked,checkItems:parseChecklist(v('checkItems'),x.checkItems)};if(section==='appearance')body={code:v('code'),labelEn:v('labelEn'),labelZh:v('labelZh'),active:$('admin-active').checked};if(section==='bom')body={modelId:Number(v('modelId')),sku:v('sku'),descriptionEn:v('descriptionEn'),descriptionZh:v('descriptionZh'),unit:v('unit'),active:$('admin-active').checked,...(v('standardQty')?{standardQty:Number(v('standardQty'))}:x.quantityControl?{standardQty:null}:{})};try{await api('/api/admin/'+section+(editing?'/'+encodeURIComponent(x.id||x.code):''),{method:editing?'PUT':'POST',body});state.dirty=false;await loadCatalog();await loadAdmin();notice(t('Saved successfully'));}catch(err){$('admin-error').hidden=false;$('admin-error').textContent=errorMessage(err);}});bind('admin-reset-form','submit',async ev=>{ev.preventDefault();try{await api('/api/admin/users/'+x.id+'/password',{method:'POST',body:{password:$('admin-reset-password').value}});$('admin-reset-password').value='';$('admin-reset-result').textContent=t('Password updated');}catch(err){$('admin-reset-result').textContent=errorMessage(err);}});
}
window.addEventListener('beforeunload',ev=>{if(state.dirty||state.photoDraft){ev.preventDefault();ev.returnValue='';}});
try{state.session=await api('/api/session');if(state.session.user){state.lang=state.session.user.language==='zh'?'zh':'en';await loadCatalog();await loadRecords();}else renderLogin();}catch(err){$('app').textContent=err.message;}
